import {verifyInfiniteReceipt} from './verify-infinite.js';
const pinned={"projectionSha256": "977edd46ea8bf657a47e01d5203d06630a5571c335f30190db266557a18b7f78", "targetIdentitySha256": "a23b0647fc4aa2e7919ffb5d9f0d2d5faf0d887845f7afc7263bc6e45766932f"};
const en=document.documentElement.lang==='en';
const button=document.querySelector('#run-infinite'),status=document.querySelector('#infinite-replay-status'),body=document.querySelector('#infinite-replay-body'),download=document.querySelector('#download-infinite-report');
let receipt,report;
try{const r=await fetch('./data/complete-infinite-scf-receipt-r72p.json',{cache:'no-cache'});if(!r.ok)throw new Error('HTTP '+r.status);receipt=await r.json();button.disabled=false;}catch(e){status.textContent=en?'Receipt unavailable':'证书未能读取';body.textContent=e.message;}
button.onclick=async()=>{button.disabled=true;download.hidden=true;report=null;try{const r=await verifyInfiniteReceipt(receipt,pinned);report={...r,verifiedAt:new Date().toISOString()};status.textContent=en?'Composition verified':'合成复核通过';status.className='badge success';body.replaceChildren();const p=document.createElement('p');p.textContent=en?'Source identity, whole-chart stability, strict fresh-source boundary margin, occupied rank and complete-response identities passed.':'源身份、整球稳定性、严格源误差余量、占据秩与完整响应身份均通过。';body.append(p);download.hidden=false;}catch(e){status.textContent=en?'Verification failed':'复核失败';status.className='badge failure';body.textContent=e.message;}finally{button.disabled=false;}};
download.onclick=()=>{if(!report)return;const u=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='infinite-scf-composition-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
